    engineCheckEntitlement: {
        parameters: {
            query: {
                /**
                 * @description External customer ID, derived by the trusted merchant backend. With the internal credential and an `X-Nozle-Customer-Id` header, it must equal that header or the response is `403`.
                 * @example cust_123
                 */
                customer_id: string;
                /**
                 * @description Feature code to check.
                 * @example ai_messages
                 */
                feature: string;
                /** @description External ID of one current subscription of the customer. That subscription is evaluated. An unknown or ended one answers `no_subscription`. */
                subscription_id?: string;
                /** @description External ID of an Entity. The Entity's own subscription is evaluated, else the customer's own subscription. With `subscription_id` too, the subscription must belong to that Entity. */
                entity_id?: string;
                /**
                 * @description URL-encoded JSON object of event properties. The cost estimate uses it to evaluate Cost Sheet conditions and quantities. For a sum Feature, the revenue estimate reads the call's units from the Feature's `field_name` in it. It does not filter usage, so `used`, `limit` and `remaining` cover all of the feature's usage. A value that is not a JSON object returns `400`.
                 * @example {"model":"gpt-4o","input_tokens":1200}
                 */
                metadata?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Entitlement decision. A denial is also a `200` with `allowed` set to `false`. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["PlatformCanResponse"];
                };
            };
            400: components["responses"]["EngineBadRequest"];
            401: components["responses"]["EngineUnauthorized"];
            /** @description Engine 2.22.0. `customer_payment_overdue`: the customer's unpaid invoices are past the grace of their plan and their [dunning policy](/guides/billing/dunning) blocks them. The body carries the denial (`allowed`, `reason`) and the error (`code`, `error`). Checked once the customer's subscription is found. The Node SDK 0.23.0 returns it from `can()` as a denial. A suspended workspace gets `workspace_suspended` (`code` and `error` only), which the SDKs throw. */
            402: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "allowed": false,
                     *       "reason": "customer_payment_overdue",
                     *       "code": "customer_payment_overdue",
                     *       "error": "This customer's invoices are unpaid past their grace period. Usage resumes once they are paid."
                     *     }
                     */
                    "application/json": {
                        /** @enum {boolean} */
                        allowed: false;
                        /** @enum {string} */
                        reason: "customer_payment_overdue";
                        /** @enum {string} */
                        code: "customer_payment_overdue";
                        error: string;
                    };
                };
            };
            403: components["responses"]["EngineForbidden"];
            /** @description A dependency is unavailable. With `code: usage_unavailable` the usage counter could not be read; retry after the `Retry-After` seconds and quote `request_id` to support. Subscription access and API key verification failures return an `error` without a `code`. */
            503: {
                headers: {
                    /** @description Seconds to wait before retrying. Sent with `code` `usage_unavailable` (value `1`). */
                    "Retry-After"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["EngineError"];
                };
            };
        };
    };
